value.text:
name: github-pr-auto-review
purpose: Réaliser une review automatique d'une Pull Request GitHub avec GitHub Copilot, publier les commentaires dans le diff, approuver ou demander des changements, puis nettoyer le clone.

caller_inputs:
  pullRequestUrl:
    type: string
    required: true
    default: https://fixture.invalid/change
  reviewInstructions:
    type: string
    required: true
    description: Texte fourni à l'exécution qui explique ce qu'il faut reviewer.

caller_outputs:
  pullRequestSummary:
    type: string
  reviewDecision:
    type: string
    enum: [APPROVE, REQUEST_CHANGES]
  inlineCommentCount:
    type: integer
  checksSummary:
    type: object
  cleanupStatus:
    type: string

constraints:
  - Ne jamais demander une review du YAML du workflow pendant l'exécution.
  - La configuration hôte, les credentials GitHub/Copilot et l'enregistrement de l'agent appartiennent à l'hôte.
  - Le répertoire .GnOuGo est réservé à l'état interne.
  - Tous les fichiers créés par le workflow doivent être sous workflows/github-pr-auto-review.
  - Réaliser un unique clone du projet, puis effectuer tout le travail uniquement dans ce répertoire cloné.
  - Ne pas filtrer ni dédupliquer les findings avant publication, sauf impossibilité technique de positionnement dans le diff.
  - Quoi qu'il arrive, supprimer le répertoire cloné en fin d'exécution.

policy:
  approval: strict_quality_gate
  approve_when:
    - l'installation des dépendances réussit ou aucune dépendance installable n'est détectée avec justification
    - les linters détectés réussissent ou aucun linter n'est présent avec justification
    - les tests unitaires détectés réussissent ou aucun test unitaire n'est présent avec justification
    - les tests d'intégration détectés réussissent ou aucun test d'intégration n'est présent avec justification
    - aucune anomalie bloquante High ou Critical n'est identifiée par la review Copilot ou par les consignes utilisateur
  request_changes_when:
    - échec d'installation, lint ou tests détectés
    - anomalie bloquante High ou Critical
    - impossibilité d'évaluer correctement la PR pour une raison imputable au contenu du dépôt ou aux changements

steps:
  - id: parse_pull_request_url
    action: parse
    input: ${pullRequestUrl}
    outputs: [owner, repo, pullNumber]
    validation:
      owner: ExampleOrg
      repo: ExampleProject
      pullNumber: 610

  - id: prepare_workspace
    action: filesystem.create_directory
    path: workflows/github-pr-auto-review/${run.id}

  - id: read_pull_request_metadata
    action: github.pull_request_read
    with:
      owner: ${owner}
      repo: ${repo}
      pullNumber: ${pullNumber}
      include: [base, head, commits, files, existing_reviews, existing_review_comments, check_runs]
    outputs: [baseRef, baseSha, headRef, headSha, headRepoCloneUrl, files, existingReviewComments, checkRuns]

  - id: clone_repository_once
    action: git.clone
    with:
      remoteUrl: ${headRepoCloneUrl}
      targetDirectory: workflows/github-pr-auto-review/${run.id}/repo
      branch: ${headRef}
      fetchAllBranches: true
      historyDepth: 0
    outputs: [projectRoot]

  - id: ensure_pull_request_head
    action: git.checkout
    workingDirectory: ${projectRoot}
    with:
      ref: ${headSha}

  - id: collect_project_facts
    action: project.inspect
    workingDirectory: ${projectRoot}
    outputs:
      - packageManagers
      - solutionFiles
      - projectFiles
      - testProjects
      - lintScripts
      - integrationTestMarkers
      - dependencyInstallCommands
      - unitTestCommands
      - integrationTestCommands
      - linterCommands

  - id: install_dependencies
    action: shell.run_detected_commands
    workingDirectory: ${projectRoot}
    commands: ${dependencyInstallCommands}
    continueOnError: true
    outputs: [installResults]
    notes:
      - Exemples de détection: npm ci, yarn install --frozen-lockfile, pnpm install --frozen-lockfile, dotnet restore, mvn dependency:resolve, gradle dependencies.

  - id: run_linters
    action: shell.run_detected_commands
    workingDirectory: ${projectRoot}
    commands: ${linterCommands}
    continueOnError: true
    outputs: [lintResults]

  - id: run_unit_tests
    action: shell.run_detected_commands
    workingDirectory: ${projectRoot}
    commands: ${unitTestCommands}
    continueOnError: true
    outputs: [unitTestResults]

  - id: run_integration_tests
    action: shell.run_detected_commands
    workingDirectory: ${projectRoot}
    commands: ${integrationTestCommands}
    continueOnError: true
    outputs: [integrationTestResults]

  - id: compare_pull_request
    action: git.compare_refs
    workingDirectory: ${projectRoot}
    with:
      baseRef: ${baseSha}
      headRef: ${headSha}
      compareFromMergeBase: true
    outputs: [filesJson, exactBaseSha, exactHeadSha]

  - id: copilot_review
    action: github.copilot_review
    workingDirectory: ${projectRoot}
    with:
      baseSha: ${exactBaseSha}
      headSha: ${exactHeadSha}
      filesJson: ${filesJson}
      existingCommentsJson: ${existingReviewComments}
      reviewInstructions: |
        ${reviewInstructions}

        Contraintes supplémentaires de review:
        - Réaliser la revue de code uniquement à partir du clone situé dans projectRoot et du diff exact fourni.
        - Tenir compte des résultats d'installation, lint, tests unitaires et tests d'intégration.
        - Produire des findings positionnables dans le diff quand c'est possible.
        - Les commentaires doivent être verbatim, sans caractères de contrôle.
        - Si le sujet est absent ou incertain, indiquer null/absent dans le raisonnement interne et ne pas inventer.
      runtimeContextJson:
        installResults: ${installResults}
        lintResults: ${lintResults}
        unitTestResults: ${unitTestResults}
        integrationTestResults: ${integrationTestResults}
        checkRuns: ${checkRuns}
    outputs: [findings, blockingFindingCount, coverage, copilotSummary]

  - id: create_pending_review
    action: github.pull_request_review_write
    with:
      owner: ${owner}
      repo: ${repo}
      pullNumber: ${pullNumber}
      method: create
      commitID: ${headSha}

  - id: publish_inline_comments
    action: foreach
    items: ${findings}
    noFiltering: true
    noDeduplication: true
    body:
      - action: github.add_comment_to_pending_review
        with:
          owner: ${owner}
          repo: ${repo}
          pullNumber: ${pullNumber}
          path: ${item.path}
          subjectType: LINE
          side: RIGHT
          startLine: ${item.startLine}
          line: ${item.endLine}
          body: |
            ${item.severity} — ${item.category}

            ${item.explanation}

            Evidence:
            ${item.evidence}

            Suggested patch:
            ${item.suggestedPatch}

  - id: decide_review_event
    action: evaluate
    with:
      approvalPolicy: strict_quality_gate
      installResults: ${installResults}
      lintResults: ${lintResults}
      unitTestResults: ${unitTestResults}
      integrationTestResults: ${integrationTestResults}
      blockingFindingCount: ${blockingFindingCount}
    outputs: [reviewDecision, decisionReasons]

  - id: submit_review
    action: github.pull_request_review_write
    with:
      owner: ${owner}
      repo: ${repo}
      pullNumber: ${pullNumber}
      method: submit_pending
      event: ${reviewDecision}
      body: |
        Review automatique GitHub Copilot terminée.

        Décision: ${reviewDecision}

        Résumé:
        ${copilotSummary}

        Quality gate:
        - Installation: ${installResults.status}
        - Linters: ${lintResults.status}
        - Tests unitaires: ${unitTestResults.status}
        - Tests d'intégration: ${integrationTestResults.status}
        - Findings bloquants: ${blockingFindingCount}

        Raisons:
        ${decisionReasons}

  - id: add_conversation_summary
    action: github.add_issue_comment
    with:
      owner: ${owner}
      repo: ${repo}
      issue_number: ${pullNumber}
      body: |
        Résumé court de la Pull Request:
        - Décision: ${reviewDecision}
        - Commentaires inline publiés: ${count(findings)}
        - Installation: ${installResults.status}
        - Linters: ${lintResults.status}
        - Tests unitaires: ${unitTestResults.status}
        - Tests d'intégration: ${integrationTestResults.status}
        - Couverture review: ${coverage.reviewedFiles}/${coverage.totalFiles} fichiers, ${coverage.truncatedFiles} tronqués, ${coverage.skippedFiles} ignorés.

        ${copilotSummary}

finally:
  - id: cleanup_clone
    action: filesystem.delete_directory
    path: workflows/github-pr-auto-review/${run.id}/repo
    mustRun: true
    outputs: [cleanupStatus]

return:
  pullRequestSummary: |
    PR ${owner}/${repo}#${pullNumber}: ${reviewDecision}. Inline comments: ${count(findings)}. Installation: ${installResults.status}; lint: ${lintResults.status}; unit tests: ${unitTestResults.status}; integration tests: ${integrationTestResults.status}. Cleanup: ${cleanupStatus}.
  reviewDecision: ${reviewDecision}
  inlineCommentCount: ${count(findings)}
  checksSummary:
    install: ${installResults}
    lint: ${lintResults}
    unitTests: ${unitTestResults}
    integrationTests: ${integrationTestResults}
    copilotCoverage: ${coverage}
  cleanupStatus: ${cleanupStatus}
